// Extract and normalize incoming inquiry payload
const data = $input.item.json.body || $input.item.json;

const fullName = data.fullName || data.customerName || data.name || "Valued Client";
let rawPhone = String(data.phone || data.whatsapp || "").replace(/[^0-9]/g, "");

// Format phone for Pakistan international standard (923XXXXXXXXX)
if (rawPhone.startsWith("03")) {
  rawPhone = "92" + rawPhone.substring(1);
} else if (rawPhone.startsWith("3") && rawPhone.length === 10) {
  rawPhone = "92" + rawPhone;
}

const email = data.email || "";
const category = (data.category || "general").toLowerCase(); // property, furniture, event, digital_services
const itemTitle = data.itemTitle || data.listingTitle || "General Catalog";
const itemId = data.itemId || data.listingId || "";
const userMessage = data.message || "Looking for more details";
const budget = data.budget || "Not specified";
const city = data.city || "Pakistan";
const leadId = `LEAD-${new Date().getFullYear()}-${Math.floor(1000 + Math.random() * 9000)}`;

return [{
  json: {
    leadId,
    fullName,
    phone: rawPhone,
    email,
    category,
    itemTitle,
    itemId,
    userMessage,
    budget,
    city,
    createdAt: new Date().toISOString(),
    status: "new"
  }
}];

